    89→    variantStyles[variant],
    90→    className
    91→  );
    92→
    93→  const content = (
    94→    <>
    95→      {icon && iconPosition === "left" && icon}
    96→      {children}
    97→      {icon && iconPosition === "right" && icon}
    98→    </>
    99→  );
   100→
   101→  if (as === "link") {
   102→    const { href, ...linkProps } = props as BrutalistButtonAsLink;
   103→    return (
   104→      <Link href={href} className={combinedClassName} {...linkProps}>
   105→        {content}
   106→      </Link>
   107→    );
   108→  }
   109→
   110→  return (
